-- Buying-guide intros for the nine renewable-energy categories (src/i18n/renewables.ts, categoryIntro), 2026-10-27.
-- Each language changes only while the row still holds the text first seeded from scripts/catalog/categories.mjs,
-- so an intro edited in the admin (Kategoritë) stays as the admin left it. The new texts are also in categories.mjs,
-- so a fresh seed matches.

UPDATE categories SET intro_sq = 'Panele fotovoltaike me fletë teknike publike. Krahasoni fuqinë (Wp), efikasitetin, koeficientin e temperaturës dhe çmimin për Wp; garancia e produktit dhe ajo e performancës janë dy gjëra të ndryshme. Në Shqipëri 1 kWp panele prodhon në vit nga 1 358 kWh në Kukës deri në 1 521 kWh në Fier.' WHERE slug_en = 'solar-panels' AND intro_sq = 'Module fotovoltaike nga prodhues me fletë teknike publike. Krahasoni fuqinë, efikasitetin dhe çmimin për vat.';
UPDATE categories SET intro_en = 'Photovoltaic modules with public datasheets. Compare rated power (Wp), efficiency, the temperature coefficient and the price per Wp; the product warranty and the performance warranty are two different things. In Albania 1 kWp of panels makes from 1,358 kWh a year in Kukës to 1,521 kWh in Fier.' WHERE slug_en = 'solar-panels' AND intro_en = 'Photovoltaic modules from makers with public datasheets. Compare power, efficiency and the price per watt.';
UPDATE categories SET intro_sq = 'Inverteri e kthen rrymën e paneleve në rrymë për shtëpinë dhe rrjetin. Zgjidhni njëfazor ose trefazor sipas lidhjes suaj, shikoni sa MPPT ka dhe sa kWp panele pranon, dhe merrni një hibrid nëse do të shtoni bateri.' WHERE slug_en = 'inverters' AND intro_sq = 'Inverterë të lidhur me rrjetin (on-grid) dhe hibridë, njëfazorë dhe trefazorë. Shikoni sa MPPT kanë dhe nëse mund të lidhen me bateri.';
UPDATE categories SET intro_en = 'The inverter turns the panels’ current into power for the house and the grid. Choose single or three phase to match your connection, check how many MPPTs it has and how many kWp of panels it accepts, and take a hybrid if you will add a battery.' WHERE slug_en = 'inverters' AND intro_en = 'Grid-tied and hybrid inverters, single and three phase. Check the MPPT count and whether they can take a battery.';
UPDATE categories SET intro_sq = 'Bateri litiumi për të përdorur në mbrëmje energjinë e paneleve. Krahasoni kapacitetin e përdorshëm, jo atë nominal, dhe çmimin për kWh. Bateritë me tension të lartë dhe ato 48 V nuk zëvendësojnë njëra-tjetrën: kontrolloni që inverteri juaj e mbështet modelin.' WHERE slug_en = 'batteries' AND intro_sq = 'Bateri litiumi për shtëpi dhe biznese. Krahasoni kapacitetin e përdorshëm dhe çmimin për kWh.';
UPDATE categories SET intro_en = 'Lithium batteries to use the panels’ energy in the evening. Compare usable capacity, not nominal, and the price per kWh. High-voltage and 48 V batteries do not replace each other: check that your inverter supports the model.' WHERE slug_en = 'batteries' AND intro_en = 'Lithium batteries for homes and businesses. Compare usable capacity and the price per kWh.';
UPDATE categories SET intro_sq = 'Pompa nxehtësie ajër–ujë për ngrohje, ujë të ngrohtë dhe, te disa modele, ftohje. COP tregon sa kWh nxehtësi jep pompa për 1 kWh energji elektrike, me ajrin jashtë 7 °C dhe ujin 35 °C; SCOP është mesatarja e sezonit. Fuqinë e duhur e llogarit instaluesi nga humbjet e nxehtësisë së shtëpisë.' WHERE slug_en = 'heat-pumps' AND intro_sq = 'Pompa nxehtësie ajër–ujë për ngrohje, ftohje dhe ujë të ngrohtë.';
UPDATE categories SET intro_en = 'Air-to-water heat pumps for heating, hot water and, on some models, cooling. COP tells you how many kWh of heat the pump gives per 1 kWh of electricity, with outside air at 7 °C and water at 35 °C; SCOP is the season’s average. The installer works out the right capacity from the house’s heat loss.' WHERE slug_en = 'heat-pumps' AND intro_en = 'Air-to-water heat pumps for heating, cooling and hot water.';
UPDATE categories SET intro_sq = 'Ngrohës uji diellorë me termosifon: kolektori në çati ngroh ujin, që ngjitet vetë në depozitë pa pompë. Krahasoni vëllimin e depozitës, sipërfaqen e kolektorit dhe rezistencën elektrike për ditët pa diell.' WHERE slug_en = 'solar-water-heaters' AND intro_sq = 'Sisteme termosifoni me kolektor dhe depozitë.';
UPDATE categories SET intro_en = 'Thermosiphon solar water heaters: the collector on the roof warms the water, which rises into the tank by itself, with no pump. Compare the tank volume, the collector area and the electric element for sunless days.' WHERE slug_en = 'solar-water-heaters' AND intro_en = 'Thermosiphon systems with collector and tank.';
UPDATE categories SET intro_sq = 'Karikues muri për makina elektrike. Karikuesit 22 kW në katalog janë trefazorë, prandaj kërkojnë lidhje trefazore. ERE ka një tarifë të veçantë, 22 lekë/kWh (25,3 në orët e pikut), për pikat e karikimit mbi 11 kW; karikuesi i shtëpisë deri në 11 kW mbetet me tarifën tuaj të zakonshme.' WHERE slug_en = 'ev-chargers' AND intro_sq = 'Karikues muri për makina elektrike, me lidhës Type 2.';
UPDATE categories SET intro_en = 'Wall chargers for electric cars. The 22 kW chargers in the catalogue are three-phase, so they need a three-phase connection. ERE has a separate tariff, 22 lekë/kWh (25.3 at peak hours), for charging points above 11 kW; a home charger up to 11 kW stays on your normal tariff.' WHERE slug_en = 'ev-chargers' AND intro_en = 'Wall chargers for electric cars with a Type 2 connector.';
UPDATE categories SET intro_sq = 'Matës inteligjentë për të parë prodhimin e paneleve dhe konsumin në kohë reale. Udhëzimi 3/2019 kërkon nga vetëprodhuesi dy matës me shpenzimet e tij: një matës dypalësh në lidhjen me rrjetin dhe një matës prodhimi pas inverterit. Para se të blini, pyesni OSSH-në nëse rregullat e majit 2026 e kanë ndryshuar këtë dhe cilat modele pranon.' WHERE slug_en = 'energy-monitoring' AND intro_sq = 'Matës inteligjentë për të parë prodhimin dhe konsumin në kohë reale.';
UPDATE categories SET intro_en = 'Smart meters to see the panels’ production and your consumption in real time. Instruction 3/2019 requires self-producers to fit two meters at their own cost: a two-way meter at the grid connection and a production meter after the inverter. Before you buy, ask the grid operator whether the May 2026 rules changed this and which models it accepts.' WHERE slug_en = 'energy-monitoring' AND intro_en = 'Smart meters to see production and consumption in real time.';
UPDATE categories SET intro_sq = 'Struktura për çati me tjegulla, çati të sheshta dhe çati me llamarinë. Panelet pa ajër nga pas nxehen deri në 15 °C më shumë: në një çati 30° në Tiranë prodhojnë rreth 4% më pak. Ngarkesën e erës dhe të borës prodhuesit e llogaritin për çdo çati me programet e tyre.' WHERE slug_en = 'mounting-systems' AND intro_sq = 'Struktura për çati me tjegulla, çati të sheshta dhe çati me llamarinë.';
UPDATE categories SET intro_en = 'Frames for tiled, flat and metal roofs. Panels with no air behind them run up to 15 °C hotter: on a 30° roof in Tirana they make about 4% less. Makers work out wind and snow loads for each roof with their own planning tools.' WHERE slug_en = 'mounting-systems' AND intro_en = 'Structures for tiled, flat and metal roofs.';
UPDATE categories SET intro_sq = 'Kabllo diellore, lidhës dhe ndërprerës DC për impiante fotovoltaike. Lidhësit duhet të jenë të të njëjtit lloj me ata të paneleve: shumica e paneleve në katalog vijnë me lidhës MC4-EVO2, ndërsa Amphenol H4 lidhet vetëm me H4. Seksionin e kabllos e zgjedh instaluesi sipas rrymës dhe gjatësisë së linjës.' WHERE slug_en = 'pv-accessories' AND intro_sq = 'Lidhës MC4, kabllo diellore dhe ndërprerës DC për impiante fotovoltaike.';
UPDATE categories SET intro_en = 'Solar cable, connectors and DC isolators for PV installations. Connectors must match the type on the panels: most panels in the catalogue ship with MC4-EVO2 connectors, while Amphenol H4 mates only with H4. The installer chooses the cable cross-section from the current and the length of the run.' WHERE slug_en = 'pv-accessories' AND intro_en = 'MC4 connectors, solar cable and DC isolators for PV installations.';
